(()=>{const list=document.querySelector('.recommendations-page .article-list');if(!list)return;const buttons=[...document.querySelectorAll('[data-recommendations-view]')];const setView=view=>{view=view==='grid'?'grid':'list';list.dataset.view=view;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.recommendationsView===view)));};let saved;try{saved=localStorage.getItem('lizzy-recommendations-view');}catch{}setView(saved);buttons.forEach(b=>b.addEventListener('click',()=>{setView(b.dataset.recommendationsView);try{localStorage.setItem('lizzy-recommendations-view',b.dataset.recommendationsView);}catch{}}));
const intro=document.querySelector('.recommendations-page .page-intro'),subtitle=intro.querySelector('p');function fitSubtitle(){subtitle.style.fontSize='';let size=parseFloat(getComputedStyle(subtitle).fontSize);while(intro.scrollWidth>intro.clientWidth&&size>5){size-=.25;subtitle.style.fontSize=size+'px';}}fitSubtitle();addEventListener('resize',fitSubtitle);
})();
